from typing import Any, Iterator
import csv
import os

REQUIRED_COLUMNS = ('name', 'email', 'role')
ALLOWED_ROLES = ('admin', 'editor', 'viewer')
MAX_ROWS = 10000
MAX_EMAIL_LENGTH = 254


def _clean_header(raw_header) -> list[str]:
    return [str(h or '').strip().lstrip('\ufeff').lower() for h in raw_header]


def _read_csv_rows(path: str) -> Iterator[tuple[int, dict[Any, str]]]:
    with open(path, newline='', encoding='utf-8-sig') as handle:
        reader = csv.DictReader(handle)
        header = _clean_header(reader.fieldnames or [])
        yield 1, {'__header__': header}
        reader.fieldnames = header
        for row in reader:
            yield reader.line_num, row


def _read_xlsx_rows(path: str) -> Iterator[tuple[int, dict[Any, str]]]:
    from openpyxl import load_workbook

    workbook = load_workbook(path, read_only=True, data_only=True)
    try:
        sheet = workbook.active
        header = []
        for number, cells in enumerate(sheet.iter_rows(values_only=True), 1):
            if number == 1:
                header = _clean_header(cells)
                yield 1, {'__header__': header}
                continue
            row = {}
            for index, value in enumerate(cells):
                text = '' if value is None else str(value)
                if index < len(header) and header[index]:
                    row[header[index]] = text
                elif text.strip():
                    row[None] = text
            yield number, row
    finally:
        workbook.close()


def validate_users_upload(path: str, allowed_roles=ALLOWED_ROLES, max_rows: int = MAX_ROWS) -> list[dict[str, Any]]:
    """Validate an uploaded users export (.csv or .xlsx).

    Returns a list of {"row": <spreadsheet row number, header = 1>, "errors": [reasons]}
    for every bad row. An empty list means every row is valid.
    """
    extension = os.path.splitext(path)[1].lower()
    if extension == '.csv':
        rows = _read_csv_rows(path)
    elif extension in ('.xlsx', '.xlsm'):
        rows = _read_xlsx_rows(path)
    else:
        return [{'row': 0, 'errors': ['unsupported file type; upload a .csv or .xlsx file']}]

    bad_rows, seen, count = [], set(), 0
    for number, row in rows:
        if number == 1 and '__header__' in row:
            missing = [c for c in REQUIRED_COLUMNS if c not in row['__header__']]
            if missing:
                return [{'row': 1, 'errors': [f"missing columns: {', '.join(missing)}"]}]
            continue
        if not any((v or '').strip() for k, v in row.items() if k is not None):
            continue
        count += 1
        if count > max_rows:
            bad_rows.append({'row': number, 'errors': [f'more than {max_rows} rows; stopped']})
            break
        name = (row.get('name') or '').strip()
        email = (row.get('email') or '').strip().lower()
        role = (row.get('role') or '').strip().lower()
        local, _, domain = email.partition('@')
        problems = [] if name else ['name is required']
        if None in row:
            problems.append('too many fields')
        if not email:
            problems.append('email is required')
        elif len(email) > MAX_EMAIL_LENGTH or not local or ' ' in email or '@' in domain or '.' not in domain.strip('.'):
            problems.append('email is invalid')
        elif email in seen:
            problems.append('duplicate email')
        else:
            seen.add(email)
        if not role:
            problems.append('role is required')
        elif role not in allowed_roles:
            problems.append(f"role must be one of: {', '.join(allowed_roles)}")
        if problems:
            bad_rows.append({'row': number, 'errors': problems})
    return bad_rows

